import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"内存回收","description":"","frontmatter":{"title":"内存回收","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-reclaim.md","filePath":"cs/memory-reclaim.md","lastUpdated":1789023840000}'),m={name:"cs/memory-reclaim.md"};function p(E,a,B,_,u,f){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="内存回收" tabindex="-1">内存回收 <a class="header-anchor" href="#内存回收" aria-label="Permalink to &quot;内存回收&quot;">​</a></h1><div class="epigraph"><p>空闲页不够时，内核主动收缩页 Cache、slab 与匿名驻留，而不是等到下一次缺页才 CLOCK 一页。</p><footer>—— 据 Denning 的负荷控制；Bovet、Love 对 kswapd 与 shrinker 的整理</footer></div><p><a href="/cs/slab-allocator">上一课</a>会囤页。<a href="/cs/anon-vs-file-page">文件页</a> 与匿名页都占帧。<a href="/cs/thrashing">抖动</a> 已说要减负荷。缺口是后台<strong>回收</strong>：水位（watermark）、kswapd、以及可注册的 shrinker，把可丢的页还给 buddy，供缺页与大页使用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯反应式置换：每次缺页才选牺牲，延迟打在用户指令上。内核分配（网络、VFS）失败更糟。缺口：维护低/高水位；低于低水位唤醒守护线程，扫描 LRU/CLOCK、写回脏文件页、换出匿名、调用各子系统 shrinker（dentry、inode、slab）。直接回收（direct reclaim）发生在分配路径上，可能阻塞。本课不把每条 LRU 链表名字背完。</p><p><span class="marginnote">shrinker 是回调：VFS 缓存「我可以丢多少 dentry」。回收器按压力要它们交页。与 GC 不同：这里回收的是帧，对象语义由各 cache 自己保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配失败或周期性：计算需要多少页。优先丢干净文件页（再读文件）；再写回；再换出匿名；再收缩 slab。达到高水位停止。压缩（compaction）把已用页挪到一边，拼出 buddy 高阶块给大页。OOM 仅当这些都不够。与过度提交对照：回收增加「现在能拿出的帧」，不减少已承诺的 VMA。</p>',8)),(e(),n(h,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E4%BD%8E%E4%BA%8E%E6%B0%B4%E4%BD%8D%22%5D%20--%3E%20KSW%5B%22kswapd%20%2F%20%E7%9B%B4%E6%8E%A5%E5%9B%9E%E6%94%B6%22%5D%0A%20%20KSW%20--%3E%20FILE%5B%22%E4%B8%A2%E6%88%96%E5%86%99%E5%9B%9E%E6%96%87%E4%BB%B6%E9%A1%B5%22%5D%0A%20%20KSW%20--%3E%20ANON%5B%22%E6%8D%A2%E5%87%BA%E5%8C%BF%E5%90%8D%22%5D%0A%20%20KSW%20--%3E%20SH%5B%22shrinker%20%E4%BA%A4%20cache%22%5D%0A%20%20SH%20--%3E%20BUD%5B%22%E9%A1%B5%E5%9B%9E%20buddy%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回收把 CLOCK、工作集、文件/匿名分类收成一条控制环：目标是 buddy 的低阶与高阶都有货。它解释了为何机器「内存看起来满」仍流畅——满的是 Cache，不是不可丢的匿名。文件系统课即将把「文件」当成正题；本课只要求 Cache 可收缩。不要把回收写成数据库查询计划。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PSI（压力停滞信息）的全部用户接口。不保证实时任务不被直接回收卡住——实时路径应预留或 memlock。下一课离开虚存单元：用户如何用路径与描述符看字节，而不是看帧。</p><p>后课默认：帧可以从 Cache 挤回。文件作为用户看见的字节流，下一课从零命名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>水位驱动 kswapd 与 shrinker，主动还页给 buddy。</li><li>先可丢文件页，再匿名换出；OOM 仍是最后手段。</li><li>文件字节流抽象是下一单元的第一课。</li><li>出处：Denning；Bovet and Cesati, <em>ULK</em>；Love, <em>LKD</em>。</li></ul>',7))])}const k=o(m,[["render",p]]);export{b as __pageData,k as default};
